/* ================= B3 · Assessment (firm) + organisation side of the assessment ================= */
const schemeOf = p => S.schemes.find(s => s.id === p.scheme) || S.schemes[0];
const W = w => /High/.test(w || '') ? 3 : /Low/.test(w || '') ? 1 : 2;
function caseScore(c, onlySec) {
  const p = progOf(c.prog); const sch = schemeOf(p); let num = 0, den = 0;
  qsetReqs(p.qset).filter(r => !onlySec || r.sec === onlySec).forEach(r => { const o = c.outcomes[r.ref]; if (!o) return; const lv = sch.levels.find(l => l[0] === o.o); if (!lv || lv[1] === null) return; num += lv[1] * W(r.weight); den += W(r.weight); });
  return den ? Math.round(num / den) : null;
}
const bandOf = (sch, sc) => sc == null ? '—' : (sch.bands.find(b => sc >= b[1]) || sch.bands[sch.bands.length - 1])[0];
const outTone = (sch, o) => { const lv = sch.levels.find(l => l[0] === o); return lv ? lv[2] : 'neu'; };
const fcOf = code => S.findingClasses.find(f => f.code === code) || S.findingClasses[0];
function addDays(d, n) { const x = new Date('2026-10-19T12:00:00'); x.setDate(x.getDate() + n); return x.toISOString().slice(0, 10); }
/* divergence: the organisation's own answer says one thing, the outcome another */
function divergence(c, r, o) {
  const yn = r.questions.filter(q => q.choice === 'yn').map(q => (c.answers[q.id] || {}).v).filter(Boolean);
  if (!yn.length || !o) return '';
  if (yn.every(v => v === 'Yes') && o !== 'Compliant' && !/Not applicable|Pass|Satisfactory|Optimised|Managed/.test(o)) return 'The organisation answered Yes to every question here. Explain why the outcome differs; the organisation sees this in the preview.';
  if (yn.some(v => v === 'No') && o === 'Compliant') return 'The organisation answered No to at least one question but the outcome is Compliant. Record what you saw that closes the gap.';
  return '';
}
