const fmtDT = s => { const d = new Date(s); return d.toLocaleDateString('en-GB', { day: 'numeric', month: 'short' }) + ', ' + d.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' }) + ' WAT'; };
function outCounts(c, sch) { const vals = Object.values(c.outcomes).map(x => x.o); return `<div class="row wrap gap6">${sch.levels.map(([l, , t]) => { const n = vals.filter(v => v === l).length; return n ? chip(`${n} ${l}`, t) : ''; }).join('')}</div>`; }
ACT.asTab = (t) => { ocRead(); S.ui.asTab = t; render(); };
ACT.asGo = (k) => { ocRead(); const n = qsetReqs(progOf(curCase().prog).qset).length; S.ui.rIdx = Math.max(0, Math.min(+k, n - 1)); render(); };
function ocRead() { const c = curCase(); if (!$('.oc-pick')) return; const reqs = qsetReqs(progOf(c.prog).qset); const r = reqs[Math.min(S.ui.rIdx || 0, reqs.length - 1)]; const v = ($$('input[name=oc]').find(x => x.checked) || {}).value; const note_ = val('oc-note'); if (v || note_) c.outcomes[r.ref] = Object.assign({}, c.outcomes[r.ref], v ? { o: v } : {}, { note: note_, by: persona().name }); if (c.outcomes[r.ref] && !c.outcomes[r.ref].o) delete c.outcomes[r.ref]; }
ACT.ocPick = () => { setTimeout(() => { ocRead(); render(); }); };
ACT.ocSave = () => { ocRead(); const c = curCase(); const reqs = qsetReqs(progOf(c.prog).qset); const k = S.ui.rIdx || 0; if (!c.outcomes[reqs[k].ref]) { toast('Choose an outcome', 'bad'); return; } if (c.stage === 'Submitted') c.stage = 'Assessing'; if (k < reqs.length - 1) ACT.asGo(k + 1); else { render(); toast('Outcome saved'); } };
/* information requests (threads) — shared by firm and organisation */
function threadsView(c, side) {
  const ths = c.threads || []; const qs = caseQs(c);
  return ths.length ? `<div class="col gap12">${ths.map((t, i) => { const q = qs.find(x => x.id === t.qid) || { q: '—', ref: '' }; return `<div class="card col gap12"><div class="row top"><div class="grow"><div class="cap mono muted">${esc(q.ref)}</div><div class="strong">${esc(q.q)}</div></div>${chip(t.status === 'Open' ? (side === 'org' ? 'Reply needed' : 'Waiting for reply') : 'Answered', t.status === 'Open' ? 'warn' : 'ok')}</div>
      <div class="thread">${t.msgs.map(m => `<div class="msg ${m.side}"><div class="msg-b"><div class="cap"><b>${esc(m.by)}</b> · ${esc(m.when)}</div><p class="small">${esc(m.text)}</p>${m.file ? `<span class="ev-pill">${ic('paperclip')}${esc(m.file)}</span>` : ''}</div></div>`).join('')}</div>
      ${t.status === 'Open' && side === 'org' ? `<div class="col gap8">${ta('th-r' + i, '', { attrs: 'rows="2"', ph: 'Your reply' })}<div class="row between">${btn('Attach a file', { v: 'tertiary', size: 'sm', i: 'paperclip', act: 'thAttach', arg: i })}${btn('Send reply', { size: 'sm', act: 'thReply', arg: i, test: 'th-reply' })}</div></div>` : ''}
      ${t.status === 'Answered' && side === 'firm' ? '' : ''}</div>`; }).join('')}</div>` : `<div class="card">${empty('chat-circle-dots', 'No information requests', side === 'firm' ? 'Use Ask on any answer to request more information.' : 'Your assessor has not asked for anything.')}</div>`;
}
ACT.asAsk = (qid) => { ocRead(); const q = caseQs(curCase()).find(x => x.id === qid); openDialog(`${dlgHead('Ask for more information', esc(q.q), 'chat-circle-dots')}<form class="col gap12" data-form="asAsk" data-arg="${qid}">${field('Your request', ta('ask-t', '', { attrs: 'rows="3"', ph: 'e.g. Please upload the MFA policy exceptions register.' }), { for: 'ask-t' })}<div class="row end">${btn('Cancel', { v: 'outline', act: 'closeDialog' })}${btn('Send request', { type: 'submit', test: 'ask-go' })}</div></form>`); };
ACT.form_asAsk = (f) => { const t = val('ask-t'); if (!t) { toast('Write your request', 'bad'); return; } const c = curCase(); (c.threads = c.threads || []).push({ qid: f.dataset.arg, status: 'Open', msgs: [{ side: 'firm', by: persona().name + ', ' + myFirm().name, when: '19 Oct 2026', text: t }] }); addAudit('Requested information', S.orgs[c.org].name); notify({ ws: 'organisation', i: 'chat-circle-dots', tone: 'warn', title: `${myFirm().name} asked for more information (${progOf(c.prog).name})`, go: 'org/assessment', arg: c.id + '|requests', kind: 'Approvals' }); closeDialog(); render(); toast('Request sent to the organisation', 'ok', 'chat-circle-dots'); };
ACT.thAttach = (i) => { S.ui['thFile' + i] = 'MFA exceptions register.xlsx'; toast('File attached to your reply', 'ok', 'paperclip'); };
ACT.thReply = (i) => { const c = curCase(); const t = c.threads[+i]; const txt = val('th-r' + i); if (!txt) { toast('Write a reply', 'bad'); return; } t.msgs.push({ side: 'org', by: persona().name + ', ' + S.orgs[c.org].name, when: '19 Oct 2026', text: txt, file: S.ui['thFile' + i] }); t.status = 'Answered'; S.ui['thFile' + i] = undefined; notify({ ws: 'firm', i: 'chat-circle-dots', tone: 'info', title: `${S.orgs[c.org].name} replied to your information request`, go: 'firm/assess', arg: c.id + '|requests', kind: 'Updates' }); render(); toast('Reply sent'); };
/* interviews */
ACT.ivPropose = (qid) => { const q = caseQs(curCase()).find(x => x.id === qid); openDialog(`${dlgHead('Propose interview times', esc(q.q), 'video-camera')}<form class="col gap12" data-form="ivPropose" data-arg="${qid}"><div class="grid g3" style="gap:10px">${['2026-10-27T10:00', '2026-10-28T14:00', '2026-10-29T11:00'].map((d, i) => field('Option ' + (i + 1), inp('iv-s' + i, d, { type: 'datetime-local' }), { for: 'iv-s' + i })).join('')}</div>${field('Meeting link', inp('iv-l', 'https://meet.deloitte.example/zenith-isr'), { for: 'iv-l' })}${field('Who should attend', inp('iv-w', 'Chief information security officer'), { for: 'iv-w' })}<p class="cap muted">Times are West Africa Time (WAT).</p><div class="row end">${btn('Cancel', { v: 'outline', act: 'closeDialog' })}${btn('Send to organisation', { type: 'submit', test: 'iv-go' })}</div></form>`, { wide: true }); };
ACT.form_ivPropose = (f) => { const c = curCase(); const slots = [0, 1, 2].map(i => val('iv-s' + i)).filter(Boolean); (c.interviews = c.interviews || []).push({ qid: f.dataset.arg, status: 'Times proposed', slots, link: val('iv-l'), who: val('iv-w'), at: '' }); notify({ ws: 'organisation', i: 'video-camera', tone: 'info', title: `${myFirm().name} proposed interview times`, go: 'org/assessment', arg: c.id + '|interviews', kind: 'Approvals' }); closeDialog(); render(); toast('Times sent. The organisation picks one.', 'ok', 'video-camera'); };
ACT.ivHeld = (qid) => { const iv = curCase().interviews.find(i => i.qid === qid); iv.status = 'Held'; render(); toast('Interview marked as held'); };
/* findings */
function findingsTable(c, side) {
  const fs = c.findings || [];
  return `<div class="card p0">${side === 'firm' ? `<div class="tbl-tools"><span class="small muted grow">Classes and fix deadlines come from ${esc(S.tenant.short)}'s settings.</span>${btn('Raise a finding', { size: 'sm', i: 'plus', act: 'fdNew', arg: '' })}</div>` : ''}<div class="tbl-wrap"><table class="tbl"><thead><tr><th>Class</th><th>Finding</th><th>Requirement</th><th>Fix by</th>${side ? '<th class="act-col"></th>' : ''}</tr></thead><tbody>${fs.map((f, i) => `<tr><td><span class="chip ${fcOf(f.cls).tone}" title="${esc(fcOf(f.cls).name)}">${esc(f.cls)}</span></td><td class="wrap"><div class="strong small">${esc(f.title)}</div>${f.detail ? `<div class="cap muted">${esc(f.detail)}</div>` : ''}</td><td class="mono small">${esc(f.ref)}</td><td class="small">${f.due ? fmtD(f.due) : '<span class="muted">No deadline</span>'}</td>${side ? `<td class="act-col">${btnIc('trash', 'fdDel', i, 'Remove finding')}</td>` : ''}</tr>`).join('') || `<tr><td colspan="5">${empty('flag', 'No findings', 'Raise findings from a requirement while you assess.')}</td></tr>`}</tbody></table></div></div>`;
}
ACT.fdNew = (ref) => { ocRead(); const c = curCase(); const reqs = qsetReqs(progOf(c.prog).qset); openDialog(`${dlgHead('Raise a finding', 'The organisation sees findings when the report is published, and fixes them with an action plan.', 'flag')}<form class="col gap12" data-form="fdNew">${field('Requirement', sel('fd-ref', reqs.map(r => [r.ref, r.ref + ' · ' + r.t]), ref || reqs[0].ref), { for: 'fd-ref' })}<div class="field"><label>Class</label><div class="grid g2" style="gap:8px">${S.findingClasses.map((fc, i) => `<label class="choice"><input type="radio" name="fd-c" value="${fc.code}" class="sr" ${i === 1 ? 'checked' : ''}><span class="radio"></span><span class="grow"><b>${esc(fc.code)} · ${esc(fc.name)}</b><br><span class="cap muted">${esc(fc.d)} ${fc.days ? 'Fix within ' + fc.days + ' days.' : ''}</span></span></label>`).join('')}</div></div>${field('Title', inp('fd-t', '', { ph: 'One line the organisation will understand' }), { for: 'fd-t' })}${field('Detail', ta('fd-d', '', { attrs: 'rows="2"' }), { opt: true, for: 'fd-d' })}<div class="row end">${btn('Cancel', { v: 'outline', act: 'closeDialog' })}${btn('Raise finding', { type: 'submit', test: 'fd-go' })}</div></form>`, { wide: true }); };
ACT.form_fdNew = () => { const t = val('fd-t'); if (!t) { toast('Give the finding a title', 'bad'); return; } const c = curCase(); const code = ($$('input[name=fd-c]').find(x => x.checked) || {}).value || 'MiNC'; const fc = fcOf(code); (c.findings = c.findings || []).push({ id: uid('f'), ref: val('fd-ref'), cls: code, title: t, detail: val('fd-d'), due: fc.days ? addDays('', fc.days) : '' }); closeDialog(); render(); toast(`${code} finding raised`, 'ok', 'flag'); };
ACT.fdDel = (i) => { curCase().findings.splice(+i, 1); render(); };
/* preview, quality review, sign-off */
ACT.pvShare = () => { const c = curCase(); c.previewAt = '19 Oct 2026'; if (c.stage === 'Assessing') c.stage = 'In preview'; notify({ ws: 'organisation', i: 'eye', tone: 'info', title: `${myFirm().name} shared the outcome preview (${progOf(c.prog).name})`, go: 'org/assessment', arg: c.id + '|preview', kind: 'Approvals' }); progActivity(progOf(c.prog), myFirm().name, `shared the outcome preview with ${S.orgs[c.org].name}`); render(); toast('Preview shared. The organisation can comment, not change outcomes.', 'ok', 'eye'); };
ACT.qrDo = () => { const c = curCase(); const f = myFirm(); const rv = (f.people.find(p => p.role === 'Assessor' && p.name !== c.lead && p.status === 'Active') || f.people[0]).name; c.qr = { by: rv, when: '19 Oct 2026' }; render(); toast(`Quality review recorded by ${esc(rv)}`, 'ok', 'checks'); };
ACT.soSubmit = () => { if (!val('so-decl')) { toast('Tick the sign-off confirmation', 'bad'); return; } const c = curCase(); const p = progOf(c.prog); c.signed = { by: c.lead || persona().name, when: '19 Oct 2026' }; c.stage = 'Report submitted'; c.reportAt = '19 Oct 2026'; c.score = caseScore(c); progActivity(p, myFirm().name, `submitted the report for ${S.orgs[c.org].name}`); addAudit('Submitted report', `${S.orgs[c.org].name} · ${p.name}`); notify({ ws: 'regulator', i: 'file-text', tone: 'info', title: `${myFirm().name} submitted the report for ${S.orgs[c.org].name}`, go: 'reviews', kind: 'Approvals' }); render(); toast(`Report submitted to ${esc(S.tenant.short)}`, 'ok', 'seal-check'); };

/* ---------- Organisation side: requests, interviews, outcome preview ---------- */
screen('org/assessment', {
  t: 'Assessment', layout: 'app', ws: 'organisation', crumbs: () => [['Obligations', 'org/obligations'], progOf(curCase().prog).name],
  render() {
    const c = curCase(); const p = progOf(c.prog); const tab = ui('oaTab', 'requests'); const sch = schemeOf(p); const f = S.firms[c.firm];
    const openTh = (c.threads || []).filter(t => t.status === 'Open').length; const ivs = c.interviews || [];
    let body = '';
    if (tab === 'requests') body = threadsView(c, 'org');
    if (tab === 'interviews') body = ivs.length ? `<div class="col gap12">${ivs.map((iv, i) => { const q = caseQs(c).find(x => x.id === iv.qid); return `<div class="card col gap12"><div class="row top"><div class="grow"><div class="cap mono muted">${esc(q.ref)}</div><div class="strong">${esc(q.q)}</div><div class="cap muted">Attendee: ${esc(iv.who)}</div></div>${chip(iv.status, iv.status === 'Confirmed' ? 'ok' : iv.status === 'Held' ? 'neu' : 'warn')}</div>${iv.status === 'Times proposed' ? `<div class="field"><label>Pick a time (WAT)</label><div class="grid g3" style="gap:8px">${iv.slots.map((s, k) => `<button class="choice" data-act="ivPick" data-arg="${i}|${k}" data-test="iv-pick-${k}"><span class="radio"></span><span><b class="small">${esc(fmtDT(s))}</b></span></button>`).join('')}</div></div>` : iv.at ? kv([['When', esc(fmtDT(iv.at))], ['Link', `<span class="small">${esc(iv.link)}</span>`]]) : ''}</div>`; }).join('')}</div>` : `<div class="card">${empty('video-camera', 'No interviews yet', 'Your assessor proposes times for questions that need an interview.')}</div>`;
    if (tab === 'preview') { if (!c.previewAt) body = `<div class="card">${empty('eye', 'No preview yet', p.preview ? 'Your assessor shares outcomes here before submitting the report.' : 'This programme does not use outcome preview. You see results when the report is published.')}</div>`;
      else { const reqs = qsetReqs(p.qset); const sc = caseScore(c);
        body = `${alertBox('info', 'Preview only', `These are ${esc(f.name)}'s outcomes before the report is submitted. You can comment on any of them. You cannot change them.`, '', 'eye')}
          <div class="grid side"><div class="card p0"><div class="tbl-wrap"><table class="tbl"><thead><tr><th>Requirement</th><th>Outcome</th><th>Assessor note</th><th class="act-col"></th></tr></thead><tbody>${reqs.map(r => { const o = c.outcomes[r.ref] || {}; const cm = (c.previewComments || []).find(m => m.ref === r.ref); return `<tr><td class="wrap"><span class="mono small" style="color:var(--brand-600)">${esc(r.ref)}</span> <span class="small">${esc(r.t)}</span></td><td>${o.o ? chip(o.o, outTone(sch, o.o)) : '—'}</td><td class="wrap small muted">${esc(o.note || '')}${cm ? `<div class="cap" style="color:var(--brand-600);margin-top:4px">${ic('chat-text')} Your comment: ${esc(cm.text)}</div>` : ''}</td><td class="act-col">${['Report submitted', 'In review', 'Approved', 'Scheduled', 'Held back', 'Published'].includes(c.stage) ? '' : btn(cm ? 'Edit comment' : 'Comment', { v: 'tertiary', size: 'sm', act: 'pvComment', arg: r.ref, test: 'pv-c-' + r.ref })}</td></tr>`; }).join('')}</tbody></table></div></div>
          <div class="card col gap8"><div class="overline">Score in preview</div><div class="row gap8" style="align-items:baseline"><span class="metric">${sc ?? '—'}</span><span class="small muted">${esc(bandOf(sch, sc))}</span></div>${outCounts(c, sch)}<p class="cap muted">Final scores are set when ${esc(S.tenant.short)} approves the report.</p></div></div>`; } }
    if (tab === 'answers') { S.ui.qIdx = 0; body = `<div class="card col gap8">${note('Your submitted answers are locked.', 'lock-simple')}${btn('Open your answers', { v: 'secondary', act: 'openCase', arg: c.id })}</div>`; }
    return `<div class="rh"><div class="rh-main"><div class="overline">${f ? 'Assessment by ' + esc(f.name) : 'Assessment'}</div><div class="rh-title"><h1 class="h1">${esc(p.name)}</h1>${statusChip(c.stage)}</div><div class="rh-meta">${c.submitted ? `Submitted ${esc(c.submitted)}${c.receipt ? ` · receipt <span class="mono">${esc(c.receipt)}</span>` : ''}` : 'Not submitted yet'}</div></div></div>
      ${tabs([{ id: 'requests', label: 'Requests from assessor', count: openTh || undefined }, { id: 'interviews', label: 'Interviews', count: ivs.filter(i => i.status === 'Times proposed').length || undefined }, { id: 'preview', label: 'Outcome preview' }, { id: 'answers', label: 'Your answers' }], tab, 'oaTab')}${body}`;
  }
});
ACT.oaTab = (t) => { S.ui.oaTab = t; render(); };
ACT.ivPick = (arg) => { const [i, k] = arg.split('|').map(Number); const c = curCase(); const iv = c.interviews[i]; iv.at = iv.slots[k]; iv.status = 'Confirmed'; notify({ ws: 'firm', i: 'video-camera', tone: 'ok', title: `${S.orgs[c.org].name} confirmed an interview for ${fmtDT(iv.at)}`, go: 'firm/assess', arg: c.id + '|interviews', kind: 'Updates' }); render(); toast('Interview confirmed and added to calendars', 'ok', 'video-camera'); };
ACT.pvComment = (ref) => { const c = curCase(); const cm = (c.previewComments || []).find(m => m.ref === ref); openDialog(`${dlgHead('Comment on this outcome', ref + '. The assessor sees your comment; the outcome stays theirs to decide.', 'chat-text')}<form class="col gap12" data-form="pvComment" data-arg="${ref}">${ta('pc-t', cm ? cm.text : '', { attrs: 'rows="3"' })}<div class="row end">${btn('Cancel', { v: 'outline', act: 'closeDialog' })}${btn('Send comment', { type: 'submit', test: 'pc-go' })}</div></form>`); };
ACT.form_pvComment = (f) => { const t = val('pc-t'); if (!t) { toast('Write your comment', 'bad'); return; } const c = curCase(); c.previewComments = (c.previewComments || []).filter(m => m.ref !== f.dataset.arg).concat({ ref: f.dataset.arg, text: t, by: persona().name, when: '19 Oct 2026' }); notify({ ws: 'firm', i: 'chat-text', tone: 'info', title: `${S.orgs[c.org].name} commented on the outcome preview`, go: 'firm/assess', arg: c.id + '|report', kind: 'Mentions' }); closeDialog(); render(); toast('Comment sent to the assessor'); };
ACT.openPreview = (id) => openRoute('org/assessment', id + '|preview');

/* Settings · finding classes (editable) */
screen('settings/findings', {
  t: 'Finding classes', layout: 'app', ws: 'regulator', crumbs: [['Settings', 'settings/categories'], 'Finding classes'],
  render() {
    return `${settingsHead('settings/findings')}<div class="row wrap"><p class="muted small grow">Assessors classify every finding. The class sets how soon the organisation must fix it. Changes apply to findings raised from now on.</p>${btn('Add class', { size: 'sm', i: 'plus', act: 'fcAdd' })}</div>
      <form class="card p0" data-form="fcSave"><div class="tbl-wrap"><table class="tbl"><thead><tr><th style="width:110px">Code</th><th>Name</th><th>Meaning</th><th style="width:150px">Fix within (days)</th><th style="width:150px">Colour</th><th class="act-col"></th></tr></thead><tbody>${S.findingClasses.map((f, i) => `<tr><td><input class="inp" data-fc="${i}" data-k="code" value="${esc(f.code)}" style="height:34px"></td><td><input class="inp" data-fc="${i}" data-k="name" value="${esc(f.name)}" style="height:34px"></td><td class="wrap"><input class="inp" data-fc="${i}" data-k="d" value="${esc(f.d)}" style="height:34px"></td><td><input class="inp" type="number" min="0" data-fc="${i}" data-k="days" value="${f.days}" style="height:34px"></td><td>${sel('fc-t' + i, [['bad', 'Red'], ['warn', 'Amber'], ['info', 'Blue'], ['neu', 'Grey']], f.tone, { attrs: `data-fc="${i}" data-k="tone" style="height:34px"` })}</td><td class="act-col">${btnIc('arrow-up', 'fcMove', i, 'Move up')}${btnIc('trash', 'fcDel', i, 'Remove')}</td></tr>`).join('')}</tbody></table></div>
      <div class="tbl-foot row between"><span>0 days means no fix deadline. Order sets severity, most severe first.</span>${btn('Save classes', { type: 'submit', size: 'sm', test: 'fc-save' })}</div></form>`;
  }
});
function fcRead() { $$('[data-fc]').forEach(el => { const f = S.findingClasses[+el.dataset.fc]; if (f) f[el.dataset.k] = el.dataset.k === 'days' ? Math.max(0, +el.value || 0) : el.value.trim(); }); }
ACT.form_fcSave = () => { fcRead(); if (S.findingClasses.some(f => !f.code || !f.name)) { toast('Every class needs a code and a name', 'bad'); return; } addAudit('Updated finding classes', S.findingClasses.map(f => f.code).join(', ')); render(); toast('Finding classes saved'); };
ACT.fcAdd = () => { fcRead(); S.findingClasses.push({ code: 'NEW', name: 'New class', d: '', days: 60, tone: 'info' }); render(); };
ACT.fcDel = (i) => { fcRead(); if (S.findingClasses.length <= 1) { toast('Keep at least one class', 'bad'); return; } S.findingClasses.splice(+i, 1); render(); };
ACT.fcMove = (i) => { fcRead(); i = +i; if (!i) return; const a = S.findingClasses; [a[i - 1], a[i]] = [a[i], a[i - 1]]; render(); };

